INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (1, 'erp', 'ERP · 企业资源计划', '从订单到出货、从物料到账，看懂一家工厂的经营主干', 'core', 'erp', 'ERP 管的是工厂的「计划层」与「账」：订单怎么变成生产计划、物料什么时候买、库存怎么记、成本怎么算。制造业数字化项目里，ERP 是主数据的源头，MES 的工单、物料、BOM 绝大多数从这里下发。不懂 ERP 的人做 MES，只能做界面，做不了集成。', 1, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (2, 'mes', 'MES · 制造执行系统', '车间现场那一层：工单怎么派、料怎么发、活怎么报、质量怎么追', 'core', 'mes', 'MES 管的是「计划落地到现场」这一段：ERP 说要造 1000 台，MES 决定这 1000 台在哪条线、哪个班组、什么顺序造，并把每一次报工、每一次检验、每一个批次记录下来。它是制造业数字化里离生产现场最近、也最容易做砸的一层——因为它必须适配每家工厂不同的生产形态。', 2, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (3, 'sql', 'SQL · 数据查询与分析', '制造业数字化岗位的通用底层技能，取数、排错、做报表都靠它', 'core', 'sql', '在 MES/ERP 项目里，SQL 不是加分项而是生存工具：客户说数字不对，你得当场查出来；要出一张新报表，你得自己写取数逻辑；数据迁移的校验、上线后的对账，全是 SQL。它也是本平台五条职业路径中唯一一条「每个岗位都要求」的技能。', 3, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (4, 'plc', 'PLC · 可编程逻辑控制器', '设备侧的控制大脑，做数采和设备联网绕不开的一层', 'core', 'plc', 'PLC 是工厂设备的控制核心，也是 MES 取真实设备数据的源头。做纯业务型 MES 可以只懂概念，但只要项目涉及设备联网、稼动率自动采集、产线联动，就必须能和电气工程师对上话、能读点表、能定位信号问题。这条线是 SCADA 数采岗位的主干技能。', 4, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (5, 'embedded', '嵌入式 · 边缘设备与网关', '选修加分线：当现成方案不够用时，自己动手做数采终端', 'elective', 'embedded', '这是一条选修线，不是任何岗位的准入门槛。它的价值场景很具体：老设备没有通讯口需要加装采集盒、现场需要定制化的安灯与看板硬件、断网环境需要边缘缓存。掌握它的人在 SCADA 数采方向能接下别人接不了的活，但不掌握也完全不影响主线岗位胜任。', 5, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (6, 'industrial-network', '工业网络与通讯', '车间里的数据怎么流动：从一根网线到全厂 OT 网络架构', 'core', 'network', '这条线解决一个反复出现的现实问题：MES 上线后数据断了、设备连不上、看板卡住，八成不是软件问题而是网络问题。它连接 IT 与 OT 两个世界，是 MES 实施和 SCADA 数采两类岗位的共同短板。本路线内容待建，当前只提供大纲骨架。', 6, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (7, 'linux-ops', 'Linux 与服务器运维', 'MES 系统跑在哪、怎么部署、出问题怎么查日志', 'core', 'linux', 'MES 项目交付不只是配好功能，还包括把系统装起来、跑稳定、出问题能查。很多客户没有专职运维，实施工程师就得兼这个角色。这条线覆盖从命令行基础到服务部署、日志排查、备份恢复和监控告警。本路线内容待建，当前只提供大纲骨架。', 7, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (8, 'barcode-rfid', '条码 / RFID 与自动识别', '让物料和产品在系统里有身份：编码、打印、扫描、追溯', 'core', 'barcode', '自动识别是 MES 落地的物理入口。追溯做不做得成，取决于每一个物料和产品有没有唯一身份、现场愿不愿意扫。这条线看起来简单，实际上编码规则设计不当、标签打印方案选错、扫码动作增加工人负担，都会直接让追溯项目失败。本路线内容待建，当前只提供大纲骨架。', 8, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (9, 'project-management', '项目管理与实施方法论', '把技术能力换算成按期验收的项目，管范围、管进度、管客户', 'core', 'clipboard-list', '技术做得对和项目做得成是两回事。实施类项目失败的主因很少是技术不行，而是范围没界定、客户没对齐、上线没组织好。这条线讲的是从立项到验收的组织方法：怎么问出真需求、怎么让客户签字、怎么控住不断膨胀的需求、怎么把上线那一周安排明白。它是实施与顾问岗位从「能干活」走到「能带项目」的分水岭。', 9, 'published');
INSERT OR REPLACE INTO tracks (id, slug, title, subtitle, kind, icon, summary, sort, status) VALUES (10, 'programming-dev', '二开与编程基础', '从看懂代码到独立开发定制功能，MES 二次开发岗位的技术主干', 'core', 'code', 'MES 产品没有一套能原样满足所有工厂，二次开发是行业常态。这条线面向从实施转开发、或者非科班进入工业软件的人：不追求算法与框架深度，聚焦把客户的模糊需求变成能上线、能维护、不影响后续升级的代码。它与 SQL 路线互补——SQL 解决取数，这条线解决逻辑、接口与扩展。', 10, 'published');
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (11, 1, 1, 'L1 入门', '能对着一张销售订单，讲清它在 ERP 里会依次生成哪些单据、经过哪些模块、最后如何影响库存和财务账', 14, '["能说清 ERP 八大模块（销售/计划/MRP/采购/库存/生产/成本/财务）各自负责什么，不混淆","能看懂销售订单、生产工单、采购订单、入库单、出库单五类单据的字段含义与上下游关系","能解释 MRP 的输入是什么、输出是什么，为什么它必须依赖 BOM 和库存数据","能画出 ERP 与 MES 的职责边界图，说清哪些数据由 ERP 主导、哪些由 MES 主导"]', '[]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (12, 1, 2, 'L2 中级', '能在一套 ERP 测试环境里独立跑通「接单到出货到结账」的完整业务闭环，并解释每一步的库存与成本变化', 22, '["能独立配置物料主数据的关键参数（采购提前期、安全库存、批量规则、损耗率）并说明参数错误会导致什么后果","能手工推演一次 MRP 运算结果，验证系统跑出来的计划订单是否合理","能定位「库存账实不符」的常见原因并给出核对路径","能解释标准成本与实际成本的差异从哪来、月结时怎么处理"]', '[{"title":"主数据治理：物料、BOM、供应商、客户","desc":"讲主数据为什么是 ERP 项目失败率最高的环节。逐个拆解物料主数据的关键字段（编码规则、计量单位、采购类型、计划参数）、BOM 的版本与生效日期、供应商与客户主数据的必填项。面向刚接触 ERP 配置的实施人员和甲方 IT。学完能独立审核一份物料主数据导入模板，识别出会导致 MRP 跑错的字段。"},{"title":"MRP 运算逻辑与参数实操","desc":"把 MRP 从黑盒变成可手推的算式：毛需求、可用库存、在途量、净需求、计划订单，逐层展开。讲清提前期、批量规则、安全库存三个参数如何改变输出结果。用一个三层 BOM 的例子完整跑一遍，再对比系统结果。面向需要向客户解释「为什么系统建议我买这么多」的实施顾问。学完能独立复核 MRP 建议并回答客户质疑。"},{"title":"采购与库存事务：单据流与库存账","desc":"讲采购申请、采购订单、收货、检验、入库、退货、调拨、盘点这一串事务分别在库存账上写了什么。重点讲「三方匹配」（订单-收货-发票）和为什么它能防止付错款。面向要排查库存差异的实施与运维人员。学完能根据一条库存异动记录反推出是哪张单据造成的。"},{"title":"生产工单与在制品核算","desc":"从 ERP 视角讲工单的完整生命周期：下达、发料、报工、完工入库、结案。讲清领料差异、工时差异、在制品（WIP）余额的含义。对比 ERP 报工与 MES 报工的粒度差异，说明为什么两边数据经常对不上。面向做 ERP-MES 集成的实施工程师。学完能设计一套两系统报工数据的对账方案。"},{"title":"成本核算与差异分析","desc":"讲标准成本的构成（材料/人工/制造费用）、成本卷积（Cost Rollup）怎么算、实际成本与标准成本的四类差异（价格差异、用量差异、效率差异、产能差异）分别说明什么管理问题。面向需要和财务对话的实施顾问。学完能看懂一张成本差异报表并指出异常来源。"},{"title":"期末结账与月结流程","desc":"讲月结为什么是 ERP 上线后最容易出事的环节：单据未过账、工单未结案、库存未盘点都会卡住结账。逐条列出月结检查清单和常见卡点的处理方法。面向上线后驻场支持的实施人员。学完能独立带客户走完一次月结并处理常见异常。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (13, 1, 3, 'L3 高级', '能独立负责一个 ERP 实施项目的蓝图设计阶段，输出可评审的业务蓝图与差异分析报告，并主导数据迁移与上线切换', 34, '["能主持业务调研会议，把客户的口头流程转成可落地的流程图与单据设计","能做 Fit-Gap 分析，判断哪些需求走标准功能、哪些做二开、哪些劝退","能设计并执行主数据与期初余额的迁移方案，包含校验规则与回退预案","能设计 ERP 与 MES/WMS 的集成架构，明确接口清单、触发时机、失败重试与对账机制"]', '[{"title":"ERP 实施方法论与项目全流程","desc":"讲一个 ERP 项目从售前到验收的完整阶段划分（项目准备、业务蓝图、系统实现、上线准备、上线支持），每个阶段的输入、输出、参与角色和典型时长。讲清顾问在每个阶段的角色变化。面向准备独立带项目的中级顾问。学完能独立编制一份项目实施计划并识别关键路径。"},{"title":"业务调研与蓝图设计","desc":"教怎么开调研会：问什么问题、怎么让客户说出真实流程而不是理想流程、怎么处理部门之间说法打架。讲蓝图文档的标准结构（组织架构、业务流程、单据设计、权限矩阵、报表清单）。面向要独立面对客户的顾问。学完能产出一份能过客户评审的业务蓝图。"},{"title":"Fit-Gap 分析与二次开发决策","desc":"讲怎么把客户需求逐条对标标准功能，分成「标准满足/配置满足/二开满足/流程调整/不做」五类。重点讲二开的隐性成本（升级兼容、测试成本、知识流失）和怎么向客户论证「这个需求不该做」。面向要控制项目范围的项目负责人。学完能输出一份带成本估算的差异分析清单。"},{"title":"数据迁移与期初建账","desc":"讲迁移哪些数据（主数据、期初库存、未清订单、应收应付、固定资产）、每类数据的清洗规则和校验方法。讲切换日的时点选择、账务对齐、双系统并行期的处理。面向负责上线切换的顾问。学完能设计一套带校验脚本和回退方案的迁移计划。"},{"title":"ERP-MES-WMS 集成架构设计","desc":"讲三个系统的职责边界怎么划：谁管主数据、谁管库存实时量、谁管报工明细。给出典型接口清单（BOM 下发、工单下发、报工回传、入库回传、库存同步）和每个接口的触发方式、数据量级、失败处理。面向做多系统集成的架构型顾问。学完能画出集成拓扑图并写出接口规格说明。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (21, 2, 1, 'L1 入门', '能走进一个车间，指着一条产线说清它的工位划分、工单流转方式，并说明 MES 在这条线上应该记录哪些数据', 12, '["能说清 MES 与 ERP、SCADA 的分层关系和各自的数据粒度","能解释工单、物料、报工、质量、追溯、设备、看板七个核心模块分别解决什么现场问题","能看懂一张 MES 报工界面，说出每个字段的业务含义","能描述一次完整的「工单下达到完工入库」的现场动作序列"]', '[]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (22, 2, 2, 'L2 中级', '能独立完成一个中小型 MES 项目的核心模块配置：建产线与工位、配工艺路线、配 BOM、设检验规则、跑通一张工单的全流程并产出报表', 32, '["能根据客户的生产形态（离散/流程/批量/单件）选择合适的工单与批次管理策略并说明理由","能独立搭建多层 BOM 与工艺路线，处理替代料、损耗、工序外协等常见变体","能配置质量检验体系（首检/巡检/终检/抽检规则）并跑通一次不合格品处理流程","能查询并解释稼动率、直通率、计件产量三类核心指标的计算口径与数据来源"]', '[]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (23, 2, 3, 'L3 高级', '能独立负责一个 MES 项目从调研到上线的全过程，包含需求边界界定、集成设计、上线切换和现场异常处置', 34, '["能在需求调研阶段识别出「这家工厂真正的管理痛点」，而不是照抄客户列的功能清单","能设计 MES 与 ERP/WMS/SCADA/PLM 的接口方案，含数据流向、触发时机、异常重试与对账","能设计上线切换方案，处理在制品结转、老数据接续、双轨并行等现实问题","能在产线停摆时快速定位是数据问题、配置问题、网络问题还是设备问题，并给出临时绕行方案"]', '[{"title":"MES 需求调研：从车间走出真需求","desc":"教怎么在车间做调研：跟一条线走一遍、看现场的手写表单和白板、问班组长最烦什么。讲怎么区分「老板要的看板」和「班组长要的少填一个字段」，两者优先级往往相反。给出调研提纲模板和现场记录方法。面向要独立面对客户的实施工程师。学完能输出一份基于现场事实的需求清单，而不是客户口述的功能列表。"},{"title":"生产形态适配与方案选型","desc":"对比离散装配、流水线、批量生产、流程行业、单件定制五种形态在工单粒度、报工方式、批次追溯上的根本差异。讲错配的后果：给流水线上按单件报工的方案，工人一天点几百次，项目必然被抵制。面向做售前方案的工程师。学完能根据现场观察快速判断该用哪套配置策略。"},{"title":"MES 集成架构与接口设计","desc":"给出 MES 对上（ERP）、对下（SCADA/PLC）、对旁（WMS/PLM/QMS）的完整接口地图。逐个接口讲数据方向、频率、字段、幂等设计、失败补偿。重点讲「接口对账」——两边数据差一条怎么发现。面向做多系统项目的工程师。学完能独立编写接口规格说明书。"},{"title":"上线切换与并行运行","desc":"讲上线日那天真实会发生什么：在制品怎么结转到新系统、老工单怎么收尾、工人不会用怎么办、系统崩了怎么退回纸单。给出切换检查清单、应急预案和双轨并行的成本控制方法。面向即将带队上线的负责人。学完能编制一份可执行的上线切换方案。"},{"title":"MES 数据量治理与性能问题","desc":"讲 MES 上线一两年后必然遇到的问题：报工表几千万行、看板越来越慢、追溯查询超时。讲数据分区、历史归档、索引设计、报表预聚合四类手段的适用场景与代价。面向运维期的工程师。学完能定位慢查询并给出治理方案。"},{"title":"现场异常复盘与故障处置","desc":"用真实故障场景做训练：扫码枪扫不出、报工数据丢失、工单卡在某工序、看板数字不对、设备数据断流。每个场景给出排查顺序（先看数据、再看配置、再看网络、最后看设备）和临时绕行手段。面向驻场支持人员。学完能在压力下按流程定位问题而不是乱猜。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (31, 3, 1, 'L1 入门', '能对着一张工单表和一张报工表，写出带条件过滤、分组统计和两表关联的查询，得到正确结果', 10, '["能用 SELECT 精确取出需要的列，理解 * 为什么在生产环境是坏习惯","能组合 WHERE 的比较、逻辑、IN、LIKE、BETWEEN 条件筛选数据","能用 GROUP BY 加聚合函数做分组统计，并用 HAVING 过滤分组结果","能写出 INNER JOIN 和 LEFT JOIN，说清两者结果差异的业务含义"]', '[]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (32, 3, 2, 'L2 中级', '能独立完成 MES 常见业务取数任务：稼动率、直通率、在制品、批次追溯、计件工资，并对结果的准确性负责', 24, '["能用子查询和 CTE 把复杂逻辑拆成可读的多步查询","能用窗口函数计算排名、环比、累计值和组内去重","能识别多表关联中的数据放大陷阱和 NULL 参与运算导致的错误结果","能写出带事务的数据修正脚本，并在执行前用查询验证影响行数"]', '[{"title":"子查询与 CTE：把复杂逻辑拆开","desc":"讲标量子查询、IN 子查询、EXISTS 子查询、派生表的区别与适用场景，再引入 WITH 语句把嵌套查询改写成可读的分步逻辑。用「找出本月报工量高于全厂平均值的班组」这类真实需求做贯穿案例。面向已经会写基础 JOIN 但一遇到复杂需求就卡住的人。学完能把一个绕三层的业务问题拆成清晰的 CTE 链。"},{"title":"窗口函数：排名、环比、累计","desc":"讲 ROW_NUMBER、RANK、LAG、LEAD、SUM OVER 的语法与 PARTITION BY 的分组含义。重点用制造业场景：每个工位的最新一次报工、每条产线的产量环比、批次的累计入库量、同一 SN 的多次检验取最后一次。面向要做报表和数据分析的实施人员。学完能用一句 SQL 解决过去要写循环的问题。"},{"title":"多表关联进阶与 NULL 陷阱","desc":"讲一对多关联造成的数据放大（求和翻倍是最常见的报表事故）、多个 LEFT JOIN 的顺序影响、NULL 参与比较和聚合时的静默错误、COALESCE 与 NULLIF 的用法。用「工单关联报工再关联质检，产量突然翻三倍」这个真实事故做拆解。面向出过报表事故的人。学完能在写完查询后主动做行数校验。"},{"title":"数据更新、删除与事务安全","desc":"讲 INSERT/UPDATE/DELETE 的正确姿势：先用 SELECT 验证 WHERE 条件、加事务、检查影响行数、确认后再提交。讲生产环境改数据的纪律（备份、限行数、留回退脚本）。面向要在客户生产库上操作的人。学完能安全地执行一次数据修正而不制造二次事故。"},{"title":"索引与执行计划入门","desc":"讲索引是什么、为什么能快、什么时候用不上（函数包裹字段、前导模糊匹配、隐式类型转换）。教怎么看 EXPLAIN 输出，识别全表扫描。用一条查报工明细的慢 SQL 从 8 秒优化到 200 毫秒做演示。面向被客户投诉「系统查询太慢」的人。学完能判断一条 SQL 慢在哪。"},{"title":"MES 常见业务查询模板集","desc":"汇编十来个可直接复用的查询模板：日产量统计、工序在制品、设备稼动率、一次直通率、批次正向与反向追溯、计件工资汇总、物料齐套检查、报工异常检出。每个模板给出业务口径说明和字段假设。面向要快速响应客户取数需求的实施人员。学完手上有一套能改改就用的查询库。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (33, 3, 3, 'L3 高级', '能对一个数据量千万级的 MES 库做查询性能治理，并设计报表取数模型与数据质量校验体系', 28, '["能读懂执行计划并通过改写 SQL、调整索引、拆分查询三种手段解决慢查询","能设计报表取数的中间层（视图、预聚合表、定时任务），把看板响应时间控制在秒级","能编写数据质量校验脚本，主动发现脏数据而不是等客户投诉","能在不同数据库方言（MySQL / SQL Server / SQLite / PostgreSQL）之间迁移查询逻辑"]', '[{"title":"执行计划深读与查询改写","desc":"系统讲执行计划里的扫描类型、连接算法、行数估算偏差。讲五类常见改写手法：谓词下推、去掉不必要的 DISTINCT、把 OR 拆成 UNION、把相关子查询改成 JOIN、限制中间结果集。每种给出改写前后的耗时对比。面向要做性能优化的开发型工程师。学完能独立完成一次慢查询治理。"},{"title":"索引设计与维护策略","desc":"讲复合索引的最左前缀、覆盖索引、索引选择性、写入代价。讲 MES 场景下哪些表该建什么索引（报工表按工单+时间、追溯表按 SN、库存事务表按物料+仓库）。讲索引过多导致写入变慢的实际案例。面向负责数据库设计的人。学完能为一张新表给出合理的索引方案。"},{"title":"报表取数建模与预聚合","desc":"讲为什么看板不该直接查明细表：讲物化视图、汇总表、增量刷新、定时任务四种方案的取舍。给出一套「明细层-汇总层-展示层」的分层设计。讲汇总数据与明细数据不一致时怎么排查。面向做看板和报表的工程师。学完能设计一套响应稳定的报表数据架构。"},{"title":"数据质量校验 SQL 体系","desc":"讲主动发现脏数据的方法：孤儿记录检查、重复主键检查、跨表数量对账、时间逻辑校验（完工早于开工）、数值合理性校验（报工量大于工单量）。教把这些做成定时巡检脚本并输出告警清单。面向上线后运维阶段。学完能建立一套自动化的数据体检机制。"},{"title":"数据库方言差异与迁移","desc":"对比 MySQL、SQL Server、SQLite、PostgreSQL 在分页、日期函数、字符串拼接、自增主键、UPSERT、窗口函数支持上的差异。讲跨库迁移查询时最容易踩的坑。面向要在多个客户不同数据库环境间切换的实施人员。学完能快速把一套查询适配到新数据库。"},{"title":"生产事故排查取数实战","desc":"用五个真实场景做训练：客户说产量少了、库存对不上、某批次追不到、报表和明细差一条、月结卡住。每个场景给出取数思路、验证步骤和结论表述方式。强调排查时先确认口径再查数据。面向要独立面对客户质疑的人。学完能在会议现场用 SQL 给出可信结论。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (41, 4, 1, 'L1 入门', '能看懂一份 PLC 点表，说清每个信号点代表设备的什么状态，并解释 PLC 在整个控制链路里的位置', 10, '["能说清 PLC 与继电器控制、单片机、工控机的区别和各自适用场景","能解释扫描周期、输入映像区、输出映像区这三个概念为什么决定了 PLC 的行为方式","能识别数字量输入、数字量输出、模拟量输入、模拟量输出四类 IO 及其典型接线对象","能读懂一份点表，区分状态点、报警点、计数点、参数点"]', '[]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (42, 4, 2, 'L2 中级', '能读懂一段梯形图程序的控制逻辑，并在 SCADA 或 MES 侧配置数据采集点，把设备状态取到系统里', 18, '["能读懂梯形图的常开常闭、自锁互锁、定时器计数器，说出一段程序在控什么","能解释 SCADA 在 PLC 与 MES 之间承担的角色，以及何时可以跳过 SCADA 直连","能配置一条从 PLC 到上位系统的数据采集链路并验证数据正确性","能判断一个设备状态（运行/停机/故障/待料）该用哪些信号点组合表达"]', '[]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (43, 4, 3, 'L3 高级', '能独立完成一个产线的设备数采方案设计与落地：选协议、定点表、设计握手逻辑、处理断线与异常', 26, '["能根据设备品牌与现场条件选择合适的通讯方式（Modbus TCP / S7 / OPC UA / 自由口）并说明取舍","能与电气工程师协作定义点表和地址规划，包含预留位与命名规范","能设计 MES 与设备之间的握手协议（下发配方、请求放行、结果回写）并处理超时","能定位数采链路故障：区分是 PLC 侧、网络侧、网关侧还是采集程序侧的问题"]', '[{"title":"工业通讯协议实操：Modbus / S7 / OPC UA","desc":"逐个讲三种主流通讯方式的连接参数、地址表示法、数据类型映射和调试工具。Modbus 讲寄存器类型与偏移量陷阱，S7 讲 DB 块寻址，OPC UA 讲节点浏览与订阅模式。每种给出一次完整的连通测试步骤。面向要独立配数采的工程师。学完能拿到一台陌生设备后自己把数据读出来。"},{"title":"点表设计与地址规划规范","desc":"讲点表不是电气工程师单方面给的，而是双方共同设计的接口契约。讲命名规范、地址分段规划、预留位、数据类型与量纲约定、变更管理。给出一份可复用的点表模板。面向要和电气团队协作的数采工程师。学完能主导一次点表评审会。"},{"title":"PLC 程序读改与现场安全规范","desc":"讲上位系统人员在什么情况下需要看 PLC 程序、能改什么不能改什么。重点讲现场安全纪律：不在运行设备上下载程序、改动前备份、任何改动必须电气工程师在场。讲交叉引用查找信号来源的方法。面向要进车间调试的人。学完能安全地在现场配合排查而不制造事故。"},{"title":"MES 与设备的握手协议设计","desc":"讲设备联动的三类典型场景：MES 下发生产参数到设备、设备请求 MES 放行、设备把加工结果回写 MES。每类讲状态机设计、超时处理、重复触发防护、断电恢复。讲为什么握手位必须双向确认。面向做防错与自动化产线项目的工程师。学完能设计一套不会卡死的握手流程。"},{"title":"数采链路故障诊断","desc":"给出一套分层排查方法：先 ping 通不通、再用调试工具直连读点、再看网关日志、最后看采集服务。讲常见故障特征——数据全断、数据部分缺、数据延迟、数据跳变，各自对应什么原因。面向驻场运维人员。学完能在半小时内定位一条断掉的数采链路。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (51, 5, 1, 'L1 入门', '能说清一台工业数采网关内部由哪些部分组成，并根据一个现场需求判断该买成品还是该定制', 10, '["能区分单片机、ARM Linux 板卡、工控机三类硬件的能力边界与成本区间","能说清串口（RS232/RS485）、以太网、IO 口三种接入方式的适用场景","能看懂一份工业网关的规格书，判断它能否满足现场需求","能对一个「老设备加装数采」的需求给出成品选型或定制开发的初步建议"]', '[{"title":"嵌入式与工业控制的关系","desc":"讲清嵌入式在工厂里到底出现在哪些地方：数采网关、安灯盒、扫码终端、称重仪表、边缘计算盒子。讲它与 PLC 的分工——PLC 管实时控制，嵌入式设备管数据接入与协议转换。面向做数采但没有硬件背景的软件人员。学完能在方案里正确地给嵌入式设备定位，不越界也不遗漏。"},{"title":"硬件选型：单片机 / ARM 板卡 / 工控机","desc":"横向对比三类平台在处理能力、外设接口、系统环境、功耗、成本、开发周期上的差异。给出选型决策树：只是读几个 IO 用单片机，要跑协议栈和本地缓存用 ARM Linux，要跑数据库和界面用工控机。面向要出硬件方案的工程师。学完能给出带型号和预算的选型建议。"},{"title":"串口与 IO 基础","desc":"讲 RS232 与 RS485 的电气差异、为什么工业现场普遍用 485、多机总线的接线与终端电阻、波特率与校验位的配置。讲数字量输入输出的电平标准、光耦隔离、继电器输出。面向要动手接线调试的人。学完能独立完成一次串口设备的物理连接与通讯测试。"},{"title":"工业网关的常见形态与能力","desc":"拆解市面上主流工业网关产品的功能构成：协议转换、数据缓存、边缘计算、远程配置、断网续传。讲怎么评估一款网关是否靠谱（看协议支持列表、看断网测试、看远程运维能力）。面向做设备联网选型的人。学完能列出一份网关选型评估表。"}]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (52, 5, 2, 'L2 中级', '能独立开发一个简易数采终端：读取传感器或设备信号，通过 MQTT 或 HTTP 上报到服务端', 18, '["能用 C 或 Python 完成串口读写与协议解析","能完成一次模拟量采集（温度、压力、电流）并处理量程换算与滤波","能实现 MQTT 上报，包含主题设计、QoS 选择和断线重连","能对接安灯按钮盒或状态灯，实现现场呼叫与状态回显"]', '[{"title":"C 语言与裸机开发入门","desc":"面向没有 C 语言基础的工业软件人员，只讲做数采会用到的部分：数据类型与字节序、指针与缓冲区、位运算处理状态字、结构体解析报文。用解析一帧 Modbus RTU 报文作为贯穿练习。学完能读懂并修改一段设备通讯代码。"},{"title":"传感器采集与模拟量处理","desc":"讲 4-20mA 与 0-10V 两种工业标准信号、AD 转换精度、量程换算公式、零点漂移与滤波算法（滑动平均、中位值）。用采集一路温度信号做完整实例。面向要做设备状态监测的工程师。学完能把一个物理量正确地变成系统里可用的数值。"},{"title":"MQTT 数据上报与边缘通讯","desc":"讲 MQTT 的发布订阅模型、主题层级设计（厂区/车间/产线/设备/点位）、QoS 三级的取舍、遗嘱消息用于掉线检测、断线重连与本地队列。对比 MQTT 与 HTTP 轮询在数采场景的优劣。面向做设备上云的工程师。学完能设计一套可靠的上报链路。"},{"title":"安灯与看板硬件对接","desc":"讲安灯系统的硬件构成（按钮盒、三色灯、蜂鸣器、显示屏）、呼叫信号如何进入系统、响应与关闭的闭环设计。讲电子看板的驱动方式与内容刷新机制。面向做精益改善类项目的工程师。学完能落地一套完整的现场呼叫响应系统。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (53, 5, 3, 'L3 高级', '能设计并交付一套边缘数采系统：具备本地缓存、断网续传、远程升级和长期稳定运行能力', 24, '["能说清软 PLC 的实现原理和它相对硬件 PLC 的适用边界","能设计边缘侧的本地存储与断网续传机制，保证网络恢复后数据不丢不重","能实现固件或程序的远程升级，并设计升级失败的回滚保护","能对边缘设备做长期稳定性设计：看门狗、内存泄漏防护、日志轮转、远程诊断"]', '[{"title":"边缘计算与本地缓存续传","desc":"讲为什么车间网络一定会断，以及断网期间数据怎么办。设计本地环形缓冲或嵌入式数据库存储、恢复后的补传策略、去重与顺序保证、缓存满了的丢弃策略。讲边缘侧做初步聚合以降低带宽的方法。面向要保证数据完整性的工程师。学完能设计一套断网不丢数的采集方案。"},{"title":"远程运维与固件升级","desc":"讲几十上百台分布在不同车间的边缘设备怎么管：远程配置下发、批量升级、灰度发布、失败回滚、版本一致性检查。讲升级过程断电导致设备变砖的防护设计。面向要规模化部署的工程师。学完能建立一套可管理的设备运维体系。"},{"title":"边缘设备稳定性工程","desc":"讲工业现场设备要连续跑几年不重启的现实要求。逐条讲看门狗、内存泄漏排查、文件系统只读挂载防掉电损坏、日志轮转防写满、异常自恢复。讲高温粉尘环境下的硬件可靠性考量。面向要对交付质量负责的人。学完能把一个能跑的原型做成能长期用的产品。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (61, 6, 1, 'L1 入门', '能画出一个车间从设备到服务器的网络拓扑图，标出每一段用的是什么介质和协议', 12, '["能说清 IT 网络与 OT 网络的目标差异（IT 求带宽与灵活，OT 求确定性与不中断）","能解释 IP、子网掩码、网关、VLAN 在车间组网中的实际作用","能列出常见工业协议及其典型使用场景，不把它们混为一谈","能识别一段现场布线的介质类型和潜在风险点"]', '[{"title":"工业网络分层与 IT/OT 边界","desc":"用 ISA-95 分层模型讲清从现场设备层、控制层、监控层到管理层每一层的网络特征。讲 IT 与 OT 在设计目标上的根本冲突：IT 可以为了打补丁重启，OT 停机一分钟就是钱。讲两个团队协作时的常见摩擦点。面向要在工厂里推动数字化项目的人。学完能在跨部门会议上准确表达网络需求。"},{"title":"以太网与工业以太网基础","desc":"讲标准以太网的帧结构、交换机转发原理、冲突与广播域。再讲工业以太网做了什么改造：环网冗余、确定性传输、抗干扰接头、宽温设计。对比办公交换机和工业交换机为什么价格差十倍。面向要做现场网络选型的人。学完能判断一个场景该用什么等级的网络设备。"},{"title":"IP 规划、子网与 VLAN 实战","desc":"讲车间 IP 地址怎么规划才不会一年后打架：按车间分段、按设备类型分段、预留地址池、静态与 DHCP 的选择。讲 VLAN 隔离生产网与办公网的实际配置。讲地址冲突导致产线停机的真实案例。面向要接手工厂网络的人。学完能编制一份全厂 IP 规划表。"},{"title":"工业协议全景图","desc":"横向梳理 Modbus、Profinet、EtherNet/IP、EtherCAT、CANopen、OPC UA、MQTT 各自的定位、性能等级、生态归属和典型设备。讲它们不是竞争关系而是分层共存。给出一张选型对照表。面向面对陌生设备清单需要判断怎么接入的人。学完能快速定位一台设备该用哪种方式接。"},{"title":"现场布线与交换机部署","desc":"讲车间布线的现实约束：强电干扰、油污粉尘、移动设备、距离限制。讲屏蔽双绞线与光纤的选择、走线槽规范、接地要求、交换机在配电柜里的安装。讲布线不规范导致的间歇性丢包有多难查。面向要下现场的人。学完能审查一份布线方案并指出隐患。"}]', 1);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (62, 6, 2, 'L2 中级', '能独立完成一个车间的设备接入组网：配置协议转换、验证通讯质量、用抓包工具定位问题', 22, '["能手工构造和解析一帧 Modbus 报文，判断通讯失败发生在哪一步","能配置 OPC UA 服务端与客户端，浏览节点并建立订阅","能完成一次 Profinet 或 EtherNet/IP 的设备组态与地址分配","能用抓包工具捕获并分析工业协议流量，定位丢包、超时、重传"]', '[{"title":"Modbus TCP 与 RTU 报文实操","desc":"逐字节拆解 Modbus 请求与响应报文，讲功能码、寄存器地址的偏移陷阱（协议地址与设备文档地址差 1 是最常见的坑）、字节序问题、异常码含义。用调试工具做一次完整读写。面向要独立调通设备的工程师。学完能拿着报文定位通讯错误。"},{"title":"OPC UA 服务端、客户端与信息模型","desc":"讲 OPC UA 相比传统 OPC DA 的改进：跨平台、带安全、带语义模型。讲节点、命名空间、订阅与监视项、证书与安全策略配置。做一次从服务端建模到客户端订阅的完整实践。面向做上位系统对接的人。学完能独立完成 OPC UA 链路搭建与故障排查。"},{"title":"Profinet 与 EtherNet/IP 组网配置","desc":"讲两大阵营的组态流程：设备描述文件导入、设备名与地址分配、拓扑检测、诊断信息读取。讲更换故障设备时为什么必须重新分配设备名。面向要配合电气团队做产线联网的人。学完能看懂组态界面并参与现场调试。"},{"title":"协议网关与数据转换","desc":"讲当设备协议与上位系统不匹配时的三种解法：换设备、加网关、写驱动。讲网关的配置流程、点位映射表、数据类型转换、轮询周期设置对性能的影响。讲多台网关串联导致延迟累积的问题。面向做异构设备接入的人。学完能设计一套网关部署方案。"},{"title":"抓包分析与网络故障排查","desc":"教用 Wireshark 抓工业协议流量：过滤表达式写法、TCP 重传与乱序识别、请求响应配对分析、时间差计算定位延迟来源。讲交换机镜像口配置。用一个「数据每天下午丢一次」的间歇性故障做完整排查演示。面向驻场排障人员。学完能用证据说明问题出在网络还是软件。"}]', 2);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (63, 6, 3, 'L3 高级', '能为一个新建工厂设计完整的 OT 网络架构，包含分段、冗余、安全隔离和容量规划', 28, '["能输出全厂网络架构图，含网段划分、核心与接入层设计、冗余路径","能设计 IT/OT 隔离方案（DMZ、单向网关、防火墙策略）并说明每条策略的理由","能评估数采链路的带宽与延迟需求，判断架构能否支撑规划中的设备数量","能主导一次网络故障的根因分析，输出可追溯的分析报告与改进措施"]', '[{"title":"全厂 OT 网络架构设计","desc":"讲从零设计一个工厂网络：按车间与功能划分网段、核心交换机选型与堆叠、接入层部署密度、环网冗余协议、无线覆盖规划（AGV 与 PDA 场景）。给出一份完整架构图模板与设备清单。面向参与新厂规划的工程师。学完能独立产出可评审的网络设计方案。"},{"title":"OT 安全与网络隔离","desc":"讲工业网络的真实威胁：勒索软件通过办公网横向进入产线、U 盘摆渡、远程运维通道失控。讲纵深防御设计：区域划分、DMZ 数据交换区、单向传输、白名单策略、远程访问审计。讲为什么 OT 侧不能照搬 IT 的补丁策略。面向承担安全责任的人。学完能设计一套不影响生产的隔离方案。"},{"title":"时间同步与确定性网络","desc":"讲时间不同步会造成什么后果：追溯时间线错乱、报警顺序颠倒、跨系统对账失败。讲 NTP 与 PTP 的精度差异与部署方式。讲 TSN 时间敏感网络的应用场景与现实成熟度。面向做高精度追溯与运动控制项目的人。学完能设计全厂统一的时间基准方案。"},{"title":"网络故障根因分析方法","desc":"建立一套结构化排查方法：分层定位、二分法隔离、对照实验、日志与抓包证据链。讲间歇性故障的捕获策略（长期抓包、监控埋点、环境相关性分析）。讲怎么写一份能服人的故障分析报告。面向要对故障负责的负责人。学完能把玄学问题变成有证据的结论。"},{"title":"数采链路容量规划","desc":"教怎么算：设备数量乘点位数乘采集频率等于多少数据量、网络能不能扛、采集服务能不能扛、数据库写入能不能扛。讲降频、边缘聚合、变化上报三种减负手段。讲规划不足导致上线后必须重做的案例。面向做大规模数采项目的架构者。学完能给出带数字依据的容量结论。"}]', 3);
INSERT OR REPLACE INTO track_levels (id, track_id, level, name, goal, hours, outcomes, planned_chapters, sort) VALUES (71, 7, 1, 'L1 入门', '能登录一台 Linux 服务器，独立完成文件查找、权限修改、服务启停和日志查看', 12, '["能熟练使用目录导航、文件查找、文本查看与搜索这一组日常命令","能看懂并修改文件权限与属主，理解权限不足导致服务起不来的典型场景","能用 systemctl 管理服务的启动、停止、开机自启和状态查看","能通过 SSH 安全登录服务器并完成文件上传下载"]', '[{"title":"Linux 目录结构与核心命令","desc":"讲 Linux 目录树的设计逻辑（配置在 etc、日志在 var log、程序在 usr、临时在 tmp），让人知道东西该去哪找。教一组高频命令：ls、cd、cp、mv、rm、find、grep、tail、df、du、ps、top。面向只用过 Windows 的实施人员。学完能在服务器上自主找到文件和查看运行状态。"},{"title":"用户、权限与属主","desc":"讲用户与用户组、读写执行三种权限、数字表示法、chmod 与 chown 用法。重点讲实际场景：为什么服务要用专用账号跑而不是 root、为什么上传的文件服务读不到、为什么日志目录写不进去。面向部署时反复卡在权限上的人。学完能自主诊断并修复权限问题。"},{"title":"文本编辑与处理","desc":"教 vi 的最小可用集合（进入编辑、保存退出、查找替换），再教 cat、less、head、tail -f、grep、sed、awk 处理配置文件和日志。用修改一个服务配置文件并实时跟踪启动日志作为练习。面向要在没有图形界面的服务器上干活的人。学完能独立完成配置修改。"},{"title":"软件安装与服务管理","desc":"讲包管理器（apt / yum）的安装、卸载、依赖处理，以及离线环境下的安装方法（很多工厂服务器不通外网）。讲 systemd 的服务单元文件结构、开机自启、失败自动重启配置。面向要在客户环境部署系统的人。学完能把一个应用装成随机启动的系统服务。"},{"title":"SSH 远程访问与文件传输","desc":"讲 SSH 登录、密钥认证替代密码、config 文件配置多台服务器别名、端口转发访问内网服务。讲 scp 与 rsync 传文件的差异。讲跳板机场景下的连接方式。面向要远程支持客户现场的人。学完能安全高效地远程操作服务器。"}]', 1);
